commit 8bb86935d3b0c65e3bcd41782cdd4aa915140cd8
Author: Richard Hughes <richard@hughsie.com>
Date:   Tue Apr 30 15:37:01 2024 +0100

    Do not allow creating a FuPartialInputStream out of range

    It's better to fail earlier when parsing the firmware, rather than when
    splitting the stream into chunks.
---
 libfwupdplugin/fu-partial-input-stream.c | 29 +++++++++++++++++++++++++++--
 libfwupdplugin/fu-uswid-firmware.c       |  4 +++-
 2 files changed, 30 insertions(+), 3 deletions(-)

diff --git a/libfwupdplugin/fu-partial-input-stream.c b/libfwupdplugin/fu-partial-input-stream.c
index 6c75ca051..6bde6fcbf 100644
--- a/libfwupdplugin/fu-partial-input-stream.c
+++ b/libfwupdplugin/fu-partial-input-stream.c
@@ -8,6 +8,7 @@

 #include "config.h"

+#include "fu-input-stream.h"
 #include "fu-partial-input-stream-private.h"

 /**
@@ -125,21 +126,45 @@ fu_partial_input_stream_seekable_iface_init(GSeekableIface *iface)
  * @stream: a base #GInputStream
  * @offset: offset into @stream
  * @size: size of @stream in bytes
+ * @error: (nullable): optional return location for an error
  *
  * Creates a partial input stream where content is read from the donor stream.
  *
- * Returns: (transfer full): a #FuPartialInputStream
+ * Returns: (transfer full): a #FuPartialInputStream, or %NULL on error
  *
  * Since: 2.0.0
  **/
 GInputStream *
-fu_partial_input_stream_new(GInputStream *stream, gsize offset, gsize size)
+fu_partial_input_stream_new(GInputStream *stream, gsize offset, gsize size, GError **error)
 {
+       gsize base_sz = 0;
        g_autoptr(FuPartialInputStream) self = g_object_new(FU_TYPE_PARTIAL_INPUT_STREAM, NULL);
+
        g_return_val_if_fail(G_IS_INPUT_STREAM(stream), NULL);
+       g_return_val_if_fail(error == NULL || *error == NULL, NULL);
+
        self->base_stream = g_object_ref(stream);
        self->offset = offset;
        self->size = size;
+
+       /* sanity check */
+       if (!fu_input_stream_size(stream, &base_sz, error)) {
+               g_prefix_error(error, "failed to get size: ");
+               return NULL;
+       }
+       if (offset + size > base_sz) {
+               g_set_error(error,
+                           FWUPD_ERROR,
+                           FWUPD_ERROR_INVALID_DATA,
+                           "base stream was 0x%x bytes in size, and tried to create partial "
+                           "stream @0x%x of 0x%x bytes",
+                           (guint)base_sz,
+                           (guint)offset,
+                           (guint)size);
+               return NULL;
+       }
+
+       /* success */
        return G_INPUT_STREAM(g_steal_pointer(&self));
 }

diff --git a/libfwupdplugin/fu-uswid-firmware.c b/libfwupdplugin/fu-uswid-firmware.c
index da3af6cb0..fb061e26c 100644
--- a/libfwupdplugin/fu-uswid-firmware.c
+++ b/libfwupdplugin/fu-uswid-firmware.c
@@ -120,7 +120,9 @@ fu_uswid_firmware_parse(FuFirmware *firmware,
                g_autoptr(GInputStream) istream1 = NULL;
                g_autoptr(GInputStream) istream2 = NULL;
                conv = G_CONVERTER(g_zlib_decompressor_new(G_ZLIB_COMPRESSOR_FORMAT_ZLIB));
-               istream1 = fu_partial_input_stream_new(stream, offset + hdrsz, payloadsz);
+               istream1 = fu_partial_input_stream_new(stream, offset + hdrsz, payloadsz, error);
+               if (istream1 == NULL)
+                       return FALSE;
                if (!g_seekable_seek(G_SEEKABLE(istream1), 0, G_SEEK_SET, NULL, error))
                        return FALSE;
                istream2 = g_converter_input_stream_new(istream1, conv);
commit b3a45c0016bd17950b4bdd3e187fedabb42b7f5b
Author: Richard Hughes <richard@hughsie.com>
Date:   Wed Feb 26 18:50:35 2025 +0000

    trivial: Add some error context to fu_partial_input_stream_new()

    Given a bug report of the form:

        base was 0xY bytes in size, and tried to create partial @0x0 of 0xZ bytes

    ..it's not always obvious where to even *start* debugging.
---
 libfwupdplugin/fu-uswid-firmware.c | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/libfwupdplugin/fu-uswid-firmware.c b/libfwupdplugin/fu-uswid-firmware.c
index faceb69f6..24549be67 100644
--- a/libfwupdplugin/fu-uswid-firmware.c
+++ b/libfwupdplugin/fu-uswid-firmware.c
@@ -120,8 +120,10 @@ fu_uswid_firmware_parse(FuFirmware *firmware,
                g_autoptr(GInputStream) istream2 = NULL;
                conv = G_CONVERTER(g_zlib_decompressor_new(G_ZLIB_COMPRESSOR_FORMAT_ZLIB));
                istream1 = fu_partial_input_stream_new(stream, hdrsz, payloadsz, error);
-               if (istream1 == NULL)
+               if (istream1 == NULL) {
+                       g_prefix_error(error, "failed to cut uSWID payload: ");
                        return FALSE;
+               }
                if (!g_seekable_seek(G_SEEKABLE(istream1), 0, G_SEEK_SET, NULL, error))
                        return FALSE;
                istream2 = g_converter_input_stream_new(istream1, conv);
